window.kbPageData["views/entry/k-ae4f23adb3cd8bfb"] = {"key":"entry/k-ae4f23adb3cd8bfb","state":{"route":"entry/k-ae4f23adb3cd8bfb"},"node":{"id":"k-ae4f23adb3cd8bfb","mode":"k","title":"《求是》第 15 期《加快建设健康中国》（8 月 1 日）","type":"事实与事件","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["employment","modern"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["社会治理"],"时间索引":["年度事件或数据"],"来源主题":["重要文章"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"《求是》第 15 期《加快建设健康中国》（8 月 1 日）","slug":"333789d88304"}],"directorySummary":"考点十四 《求是》第 15 期《加快建设健康中国》（8 月 1 日）\n文章指出，到 2035 年建成健康中国是中央作出的战略决策，“十五五”（2026—2030 年）是\n实现这一目标的关键时期，必须统筹谋划、加紧推进，力求取得决定性进展。要坚持从国情出\n发，坚持党对卫生与健康工作的领导，坚持人民至上…","sources":[{"id":"58e13597d6f91ece","label":"《求是》第 15 期《加快建设健康中国》（8 月 1 日）","topic":"重要文章","category":"时政","text":"考点十四 《求是》第 15 期《加快建设健康中国》（8 月 1 日）\n文章指出，到 2035 年建成健康中国是中央作出的战略决策，“十五五”（2026—2030 年）是\n实现这一目标的关键时期，必须统筹谋划、加紧推进，力求取得决定性进展。要坚持从国情出\n发，坚持党对卫生与健康工作的领导，坚持人民至上、生命至上，坚持健康优先发展战略，坚\n持基本医疗卫生事业的公益性，走中国特色卫生与健康发展道路。2016 年提出的新时代卫生\n与健康工作方针为：以基层为重点，以改革创新为动力，预防为主，中西医并重，把健康融入\n所有政策，人民共建共享。分级诊疗内涵为基层首诊、双向转诊、急慢分治、上下联动，做到\n大病不出省、一般病在市县解决、日常疾病在基层解决。","source":{"doc":"4e539a366dce19555ccf","first":20,"last":20,"page":20,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"modern","title":"中国式现代化与民生"},{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-ae4f23adb3cd8bfb":[]}};
